import{_ as t,o,c as a,a2 as r}from"./chunks/framework.Cu3jFwFD.js";const u=JSON.parse('{"title":"Combo","description":"","frontmatter":{},"headers":[],"relativePath":"features/combo/design.md","filePath":"features/combo/design.md","lastUpdated":1794904422000}'),s={name:"features/combo/design.md"};function i(n,e,d,l,h,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="combo" tabindex="-1">Combo <a class="header-anchor" href="#combo" aria-label="Permalink to &quot;Combo&quot;">​</a></h1><p><strong>Status:</strong> <span class="status-badge status-cut">CUT</span> · <strong>Updated:</strong> 2026-11-17 · <a href="./../../GDD">GDD</a></p><blockquote><p><strong>Cut on 2026-11-17 (<a class="decision-ref" href="/hex-gdd/GDD#d-029">D‑029</a>).</strong> The prototype has a delivery combo; the design does not. Why: the owner chose not to keep it. Cut ideas come back, so the prototype&#39;s rules are kept below.</p></blockquote><p>The prototype rewarded back-to-back deliveries with a growing money multiplier.</p><h2 id="what-the-prototype-did-for-reference-only" tabindex="-1">What the prototype did (for reference only) <a class="header-anchor" href="#what-the-prototype-did-for-reference-only" aria-label="Permalink to &quot;What the prototype did (for reference only)&quot;">​</a></h2><ul><li>Each delivery within 10 s of the previous one raised the combo by 1. An empty timer bar dropped it by 1.</li><li>Multiplier = 1 + 0.25 × (combo − 1), capped at ×3. A failed Chance delivery reset it to 0.</li><li>The bonus was paid on top of the normal pay.</li></ul><h2 id="consequences-of-the-cut" tabindex="-1">Consequences of the cut <a class="header-anchor" href="#consequences-of-the-cut" aria-label="Permalink to &quot;Consequences of the cut&quot;">​</a></h2><ul><li>Income per day falls (the prototype quota of $600 was tuned with the multiplier), so the quota must be re-tuned (<a href="./../run-and-quota/design">run-and-quota</a>).</li><li>Nothing else in the design depends on it.</li><li>Removing the code and HUD from the prototype is a separate task.</li></ul><h2 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h2><ul><li>2026-11-17: cut, <a class="decision-ref" href="/hex-gdd/GDD#d-029">D‑029</a>.</li></ul>',10)])])}const f=t(s,[["render",i]]);export{u as __pageData,f as default};
